const risposta = await fetch('/api/libri/1', {
  method: 'PATCH',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ titolo: 'Solaris aggiornato' })
});
// fetch non rifiuta automaticamente un 404: verificare status.
if (!risposta.ok) throw new Error(`HTTP ${risposta.status}`);
const libro = await risposta.json();
console.log(libro.titolo);

Sul server PATCH valida il titolo, restituisce 400 per body invalido, 404 per id assente e jsonify(libro), 200 dopo aggiornamento.

